param(
    [string]$ProjectPath = "C:\Users\kymfe\OneDrive\Desktop\Zevo Audit",
    [string]$ContactEmail = ""
)

$ErrorActionPreference = "Stop"
$indexPath = Join-Path $ProjectPath "index.html"
$assetPath = Join-Path $ProjectPath "zevo-audit-landing.png"

if (-not (Test-Path -LiteralPath $indexPath)) {
    throw "index.html was not found at: $indexPath"
}

$html = Get-Content -LiteralPath $indexPath -Raw -Encoding UTF8

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupPath = Join-Path $ProjectPath "index.before-exact-landing-$timestamp.html"
Copy-Item -LiteralPath $indexPath -Destination $backupPath
Write-Host "Backup created: $backupPath" -ForegroundColor DarkGray

# Remove the previous approximate landing page, if present.
$html = [regex]::Replace($html, '(?s)\r?\n?/\* ===== ZEVO AUDIT LANDING / COVER ===== \*/.*?/\* ===== END ZEVO AUDIT LANDING ===== \*/\r?\n?', "")
$html = [regex]::Replace($html, '(?s)\r?\n?<!-- ZEVO_AUDIT_LANDING_START -->.*?<!-- ZEVO_AUDIT_LANDING_END -->\r?\n?', "")
$html = [regex]::Replace($html, '(?s)\r?\n?<script id="zevo-audit-landing-controller">.*?</script>\r?\n?', "")

# Remove this exact installer if it has already been run, so reruns are safe.
$html = [regex]::Replace($html, '(?s)\r?\n?/\* ===== ZEVO EXACT LANDING START ===== \*/.*?/\* ===== ZEVO EXACT LANDING END ===== \*/\r?\n?', "")
$html = [regex]::Replace($html, '(?s)\r?\n?<!-- ZEVO_EXACT_LANDING_START -->.*?<!-- ZEVO_EXACT_LANDING_END -->\r?\n?', "")
$html = [regex]::Replace($html, '(?s)\r?\n?<script id="zevo-exact-landing-controller">.*?</script>\r?\n?', "")

# Normalize any hidden class left by the previous installer.
$html = $html.Replace('<div class="app audit-app-hidden">', '<div class="app">')
$html = $html.Replace('<div class="app zevo-audit-app-hidden">', '<div class="app">')

if (-not $html.Contains('</style>') -or -not $html.Contains('<body>') -or -not $html.Contains('<div class="app">') -or -not $html.Contains('</body>')) {
    throw "The expected index.html structure was not found. No changes were written."
}

