'@
[IO.File]::WriteAllBytes($assetPath, [Convert]::FromBase64String(($imageBase64 -replace '\s','')))
Write-Host "Landing asset written: $assetPath" -ForegroundColor DarkGray

$contactHotspot = ""
if ($ContactEmail.Trim()) {
    $safeEmail = [System.Net.WebUtility]::HtmlEncode($ContactEmail.Trim())
    $contactHotspot = '<a class="zevo-exact-hotspot zevo-hot-contact" href="mailto:' + $safeEmail + '" aria-label="Contact Kym Feltus"></a>'
}

$css = @'

/* ===== ZEVO EXACT LANDING START ===== */
.zevo-audit-app-hidden{display:none!important}
.zevo-exact-landing[hidden]{display:none!important}
body.zevo-exact-open{margin:0!important;background:#050507!important;overflow-x:hidden!important}
.zevo-exact-landing{
  min-height:100vh;
  width:100%;
  background:#050507;
  display:flex;
  justify-content:center;
  align-items:flex-start;
  overflow-x:hidden;
  position:relative;
  z-index:9999;
}
.zevo-exact-stage{
  width:min(100vw,1440px);
  position:relative;
  margin:0 auto;
  line-height:0;
  background:#050507;
  box-shadow:0 0 120px rgba(74,24,130,.12);
}
.zevo-exact-stage>img{
  display:block;
  width:100%;
  height:auto;
  margin:0;
  user-select:none;
  -webkit-user-drag:none;
  pointer-events:none;
}
.zevo-exact-hotspot{
  position:absolute;
  z-index:3;
  display:block;
  padding:0;
  margin:0;
  border:0;
  background:transparent;
  color:transparent;
  text-indent:-9999px;
  overflow:hidden;
  cursor:pointer;
  appearance:none;
  -webkit-appearance:none;
  border-radius:10px;
}
.zevo-exact-hotspot:hover{background:rgba(190,116,255,.025)}
.zevo-exact-hotspot:focus-visible{
  outline:2px solid rgba(218,145,255,.95);
  outline-offset:2px;
  background:rgba(190,116,255,.035)
}
/* Hotspots are percentage-based against the approved 1086x1448 master artwork. */
.zevo-hot-overview{left:58.1%;top:1.15%;width:8.2%;height:3.5%}
.zevo-hot-findings{left:69.1%;top:1.15%;width:8.5%;height:3.5%}
.zevo-hot-evidence-nav{left:79.3%;top:1.15%;width:8.5%;height:3.5%}
.zevo-hot-contact{left:89.4%;top:1.15%;width:8.6%;height:3.5%}
.zevo-hot-findings-cta{left:3.75%;top:34.55%;width:24.5%;height:4.25%}
.zevo-hot-evidence-cta{left:29.6%;top:34.55%;width:20.6%;height:4.25%}
.zevo-hot-evidence-preview{left:47.0%;top:78.8%;width:48.5%;height:13.0%}
@media(max-width:700px){
  .zevo-exact-stage{width:100vw}
  .zevo-exact-hotspot{border-radius:5px}
}
/* ===== ZEVO EXACT LANDING END ===== */
'@

$landing = @"
<!-- ZEVO_EXACT_LANDING_START -->
<section class="zevo-exact-landing" id="zevo-exact-landing" aria-label="ZEVO Corp Audit landing page">
  <div class="zevo-exact-stage">
    <img src="zevo-audit-landing.png" alt="ZEVO Corp Audit — an audit conducted by Kym Feltus, FELTUS LABS" width="1086" height="1448" />
    <button class="zevo-exact-hotspot zevo-hot-overview" type="button" data-cover-home aria-label="Overview">Overview</button>
    <button class="zevo-exact-hotspot zevo-hot-findings" type="button" data-enter-audit="overview" aria-label="Open audit findings">Findings</button>
    <button class="zevo-exact-hotspot zevo-hot-evidence-nav" type="button" data-enter-audit="evidence" aria-label="Open evidence">Evidence</button>
    $contactHotspot
    <button class="zevo-exact-hotspot zevo-hot-findings-cta" type="button" data-enter-audit="overview" aria-label="View Audit Findings">View Audit Findings</button>
    <button class="zevo-exact-hotspot zevo-hot-evidence-cta" type="button" data-enter-audit="evidence" aria-label="Open Evidence">Open Evidence</button>
    <button class="zevo-exact-hotspot zevo-hot-evidence-preview" type="button" data-enter-audit="evidence" aria-label="Open evidence preview">Evidence Preview</button>
  </div>
</section>
<!-- ZEVO_EXACT_LANDING_END -->
"@

$js = @'
<script id="zevo-exact-landing-controller">
(function(){
  const landing=document.getElementById('zevo-exact-landing');
  const app=document.querySelector('.app');
  if(!landing||!app)return;

  function isCoverView(){
    const view=(location.hash||'').replace('#','').trim();
    return !view || view==='landing';
  }
  function syncCover(){
    const show=isCoverView();
    landing.hidden=!show;
    app.classList.toggle('zevo-audit-app-hidden',show);
    document.body.classList.toggle('zevo-exact-open',show);
    if(show) window.scrollTo(0,0);
  }
  function enterAudit(view){
    const target=view||'overview';
    if(location.hash==='#'+target){
      landing.hidden=true;
      app.classList.remove('zevo-audit-app-hidden');
      document.body.classList.remove('zevo-exact-open');
      window.dispatchEvent(new HashChangeEvent('hashchange'));
      window.scrollTo(0,0);
    } else {
      location.hash=target;
    }
  }

  document.querySelectorAll('[data-enter-audit]').forEach(function(el){
    el.addEventListener('click',function(){enterAudit(el.dataset.enterAudit);});
  });
  document.querySelectorAll('[data-cover-home]').forEach(function(el){
    el.addEventListener('click',function(){
      history.replaceState(null,'',location.pathname+location.search);
      syncCover();
    });
  });
  window.addEventListener('hashchange',syncCover);
  syncCover();
})();
</script>
'@

# Install exact CSS.
$styleIndex = $html.IndexOf('</style>')
$html = $html.Insert($styleIndex, $css)

# Install exact landing immediately after body opens.
$bodyIndex = $html.IndexOf('<body>') + '<body>'.Length
$html = $html.Insert($bodyIndex, "`r`n$landing`r`n")

# Prevent the underlying audit application from flashing on first load.
$html = $html.Replace('<div class="app">', '<div class="app zevo-audit-app-hidden">')

# Install controller before body closes.
$bodyCloseIndex = $html.LastIndexOf('</body>')
$html = $html.Insert($bodyCloseIndex, "`r`n$js`r`n")

Set-Content -LiteralPath $indexPath -Value $html -Encoding UTF8

Write-Host "" 
Write-Host "Exact ZEVO landing page installed." -ForegroundColor Green
Write-Host "Updated: $indexPath"
Write-Host "Asset:   $assetPath"
Write-Host "Backup:  $backupPath"
Write-Host ""
Write-Host "Preview:" -ForegroundColor Cyan
Write-Host "  cd `"$ProjectPath`""
Write-Host "  python -m http.server 8080"
Write-Host "  Open http://localhost:8080"
Write-Host ""
Write-Host "If approved, commit both files:" -ForegroundColor Cyan
Write-Host "  git add index.html zevo-audit-landing.png"
Write-Host "  git commit -m `"Match ZEVO landing page to approved design`""
Write-Host "  git push"
